		FormatVersion:     1,
		RepoRoot:          snapshot.Header.RepoRoot,
		Commit:            snapshot.Header.Commit,
		Tree:              snapshot.Header.Tree,
		Profile:           snapshot.Header.Profile,
		Query:             flags.Symbol,
