			return "", false
		}
		if maxReadBytes > 0 && info.Size() > maxReadBytes {
			registry.note(path, info.Size())
			return "", false
		}
		file, err := root.Open(name)
		if err != nil {
			return readFallback(pinned, repo, path, maxReadBytes, func(size int64) { registry.note(path, size) })
