}

// openContainedRegularFile is the one place the fallback readers turn a
// repository-relative path into an open file. Lstat and Open both go through the
// pinned directory handle, so the leaf cannot be a symlink and no component
// above it can be swapped between the check and the read.
func openContainedRegularFile(pinned fs.FileInfo, repo, relPath string) (*os.File, fs.FileInfo, bool) {
	dirRoot, base, ok := containedRealDir(pinned, repo, relPath)
	if !ok {
		return nil, nil, false
	}
	defer dirRoot.Close()
	info, err := dirRoot.Lstat(base)
	if err != nil || info.Mode()&fs.ModeSymlink != 0 || !info.Mode().IsRegular() {
		return nil, nil, false
	}
	file, err := dirRoot.Open(base)
	if err != nil {
		return nil, nil, false
	}
	// The size that governs the caller's bound is the one belonging to the OPEN
	// file, not to the earlier Lstat of the same name.
	opened, err := file.Stat()
	if err != nil || !opened.Mode().IsRegular() {
		_ = file.Close()
		return nil, nil, false
	}
	return file, opened, true
}

// readFallback reads relPath the way os.Root would have, had it not refused
// one of the two shapes the fallback-directory comment describes: it refuses a
// symlinked or non-regular final component exactly as the root.Lstat check
// above does, verifies containment on the resolved destination, and only then
// reads.
func readFallback(pinned fs.FileInfo, repo, relPath string, maxReadBytes int64, noteOversize func(int64)) (string, bool) {
	file, info, ok := openContainedRegularFile(pinned, repo, relPath)
	if !ok {
		return "", false
	}
	defer file.Close()
	if maxReadBytes > 0 && info.Size() > maxReadBytes {
		if noteOversize != nil {
			noteOversize(info.Size())
		}
		return "", false
	}
	content, err := io.ReadAll(file)
	if err != nil {
		return "", false
	}
	// A file that grew between the size check and the read is refused rather than
	// truncated: the bound is on what this reader may return, and half a file is
	// not a smaller answer, it is a wrong one.
	if maxReadBytes > 0 && int64(len(content)) > maxReadBytes {
		if noteOversize != nil {
			noteOversize(int64(len(content)))
		}
		return "", false
	}
	return string(content), true
}

// readPrefixFallback is readFallback's counterpart for a bounded prefix read.
func readPrefixFallback(pinned fs.FileInfo, repo, relPath string, limit int) (string, bool) {
	file, _, ok := openContainedRegularFile(pinned, repo, relPath)
	if !ok {
		return "", false
	}
	defer file.Close()
	buf := make([]byte, limit)
	n, err := io.ReadFull(file, buf)
	if err != nil && err != io.EOF && err != io.ErrUnexpectedEOF {
		return "", false
	}
	return string(buf[:n]), true
}

// openManuallyConfinedWorktreeSource builds a refusal-only worktree source for
// the defensive case where the repository root could not be held open. Without
// Package filedigest computes a file's content identity (SHA-256) and line
// count in constant memory.
//
// It exists for one purpose: a file too large to materialize must still be
// describable. Reading such a file to hash it is what makes a snapshot's memory
// scale with the largest file in the repository, so every consumer that only
// needs the file's identity streams it through here instead.
package filedigest

import (
	"crypto/sha256"
	"encoding/hex"
	"io"
	"os"
)

// streamBufferBytes is the fixed window a digest holds at any instant,
// independent of the file's size.
const streamBufferBytes = 64 * 1024

// Digest is a file's content identity and shape, computed without holding the
// content.
type Digest struct {
	Bytes int64
	Hash  string
	Lines int
}

// Stream reads r to EOF and returns its digest. Memory stays at
// streamBufferBytes regardless of how much r yields.
//
// Lines matches the snapshot's line count: the number of newline-terminated
// lines, plus a final unterminated line when one is present, and zero for empty
// input.
func Stream(r io.Reader) (Digest, error) {
	hasher := sha256.New()
	buf := make([]byte, streamBufferBytes)
	digest := Digest{}
	var last byte
	for {
		n, err := r.Read(buf)
		if n > 0 {
			chunk := buf[:n]
			_, _ = hasher.Write(chunk)
			digest.Bytes += int64(n)
			for _, b := range chunk {
				if b == '\n' {
					digest.Lines++
				}
			}
			last = chunk[n-1]
		}
		if err == io.EOF {
			break
		}
		if err != nil {
			return Digest{}, err
		}
	}
	if digest.Bytes > 0 && last != '\n' {
		digest.Lines++
	}
	digest.Hash = hex.EncodeToString(hasher.Sum(nil))
	return digest, nil
}

// File digests the file at path.
func File(path string) (Digest, error) {
	file, err := os.Open(path)
	if err != nil {
		return Digest{}, err
	}
	defer func() { _ = file.Close() }()
	return Stream(file)
}
package sem

// extractionFormatVersion is private, exact-match data identity. This payload
// is not a public graph record and is not yet persisted.
const extractionFormatVersion = 1

// extractionRecord contains file-local declarations only. Repository aliases,
// final IDs, relation resolution and synthetic boundary symbols are recomputed.
// No raw relation family is present in version 1.
type extractionRecord struct {
	Version      int
	Language     string
	Status       ParseStatus
	Declarations []extractedDeclaration
}

// extractedDeclaration explicitly preserves parser metadata that Entity JSON
// intentionally omits. Do not embed Entity: its wire shape is not this contract.
type extractedDeclaration struct {
	Kind                string
	Name                string
	Signature           string
	StartLine           int
	EndLine             int
	BodyHash            string
	Fingerprint         string
	Local               bool
	Bodyless            bool
	CLinkage            bool
	SourceStartByte     int
	SourceEndByte       int
	ParameterNames      []string
	ParameterNamesKnown bool
	ParamTypeText       string
	ReturnTypeText      string
	SignatureTypesKnown bool
}

// fileExtraction owns the freshly parsed entities. Default-off persistence does
// not pay serialization/deep-copy costs; recordExtraction makes an independent
// payload only when requested by storage or equivalence tests.
type fileExtraction struct {
	entities []Entity
	language string
	status   ParseStatus
}

func extractCapturedSource(spec profileSpec, language languageSpec, source capturedSource) fileExtraction {
	entities, name, status := parseWithProfile(TreeSitterParser{}, spec, language, source.path, source.content)
	return fileExtraction{entities: entities, language: name, status: status}
}

func recordExtraction(entities []Entity, language string, status ParseStatus) extractionRecord {
	record := extractionRecord{Version: extractionFormatVersion, Language: language, Status: status}
	if entities == nil {
